        raw"""-1/100*(Pi*(-1/10000*((1 - 10*Sqrt[r0])^2*r0^(11/2)*(1 - 15*Sqrt[r0] + 5*r0^(3/2))*((-2*I)*(-10 + OmK) + 5*((100 - 1200*I) - (20 - 120*I)*OmK + OmK^2)*r0 - (400*I)*(-10 + OmK)*r0^2 + 1000*((-10 + 20*I) + OmK)*OmK*r0^3 - (20000*I)*OmK*r0^4 + 50000*OmK^2*r0^5)) - (-10 + OmK)*r0*(I/50 - (((-10 + 80*I) + OmK)*r0)/20 + (2*I)*r0^2 - 5*OmK*r0^3)*(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4) - 10*(1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2])*(10*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4)*(1/100 + r0^2) - (1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2]) + (r0*((2*I)*(-10 + OmK) - 5*(92 - 20*OmK + OmK^2)*r0)*(-10*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4)*(1/100 + r0^2) + (1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2])^2)/20)*SS0)/(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(19/4)*(1/10 + r0^(3/2))*(1/100 - 2*r0 + r0^2)^2*(r0^(3/2)/5 + (-3 + r0)*r0^2)) - (Pi*(-2*r0*(I/50 - (((-10 + 80*I) + OmK)*r0)/20 + (2*I)*r0^2 - 5*OmK*r0^3)*(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4) - 10*(1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2])*(10*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4)*(1/100 + r0^2) - (1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2]) + (r0*(I - 5*(-10 + OmK)*r0)*(-10*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4)*(1/100 + r0^2) + (1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2])^2)/5)*SS1)/(100*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(19/4)*(1/10 + r0^(3/2))*(1/100 - 2*r0 + r0^2)^2*(r0^(3/2)/5 + (-3 + r0)*r0^2)) + (Pi*(-10*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(1/10 + (-2 + r0)*Sqrt[r0])*r0^(3/4)*(1/100 + r0^2) + (1/100 - Sqrt[r0]/5 + r0^2)*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2])^2*SS2)/(100*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(11/4)*(1/10 + r0^(3/2))*(1/100 - 2*r0 + r0^2)^2*(r0^(3/2)/5 + (-3 + r0)*r0^2))""",
        raw"""(-8*Pi*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(((1 - 10*Sqrt[r0])^2*Sqrt[r0]*(1 + (5*I)*((-10 + 40*I) + OmK)*r0 + 100*r0^2 + (500*I)*OmK*r0^3))/(80*(1 - 15*Sqrt[r0] + 5*r0^(3/2))*(1 - 200*r0 + 100*r0^2)) - ((I/8)*(-10 + OmK)*(-((1/100 - Sqrt[r0]/5 + r0^2)/(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(3/4))) + (1/10 + (-2 + r0)*Sqrt[r0])/(10*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2]))*(-1/10*(1/100 - Sqrt[r0]/5 + r0^2)/(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(3/4)) + ((1/10 + (-2 + r0)*Sqrt[r0])*(1/100 + r0^2))/Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2]))/(1/100 - 2*r0 + r0^2))*SS0)/(r0^(5/4)*(1/10 + r0^(3/2))) + ((2*I)*Pi*Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*(-((1/100 - Sqrt[r0]/5 + r0^2)/(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(3/4))) + (1/10 + (-2 + r0)*Sqrt[r0])/(10*Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2]))*(-1/10*(1/100 - Sqrt[r0]/5 + r0^2)/(Sqrt[1/5 + (-3 + r0)*Sqrt[r0]]*r0^(3/4)) + ((1/10 + (-2 + r0)*Sqrt[r0])*(1/100 + r0^2))/Sqrt[r0^(3/2)/5 + (-3 + r0)*r0^2])*SS1)/(r0^(5/4)*(1/10 + r0^(3/2))*(1/100 - 2*r0 + r0^2))""",
        raw"""-1/2*(Pi*(1 - 10*Sqrt[r0])^2*r0^(1/4)*SS0)/((1 + 10*r0^(3/2))*Sqrt[5 - 75*Sqrt[r0] + 25*r0^(3/2)])"""),
)
# Circular point-particle source δ-coefficients (PN.wl TeukolskySourceCircularOrbit,
# "Form"->"InvariantWronskian"), θ0=π/2. The three coefficients of
# {δ(r-r0), δ'(r-r0), δ''(r-r0)} as exact functions of (r0, ΩKerr); then PN-scaled
# (r0->r0 η⁻², ΩKerr->ΩKerr η³) and expanded as η-PNSeries.
#
# The (l,m) coefficients differ ONLY in the Δ-power numerators and the SWSH harmonic; the
# source STRUCTURE is shared. They are dumped from the MMA oracle as InputForm strings keyed
# by (l,m) — `_SRC_A0_LM` / `_SRC_AKERR_LM` in mode_pn_source_data.jl — and parsed GENERICALLY
# by _eval_mma_ast. At a==0 the SWSH S0,dS0,d2S0 collapse to their spin-weighted SPHERICAL
# values at θ=π/2, FOLDED INTO Sqrt[k*Pi] closed forms (no SS symbols); at a≠0 they are
# genuinely spheroidal and KEPT SYMBOLIC (SS0/SS1/SS2). R3.



# the ΩKerr symbol used by the source (= Ω_φ; ω = m ΩKerr).  Distinct from the amplitude ω.
_OMK() = Symbolics.variable(:ΩKerr)

# SWSH placeholder symbols S0, dS0, d2S0 = SpinWeightedSpheroidalHarmonicS[s,l,m,aω][π/2,0]
# and its θ-derivatives (PN.wl 1331-1333). At a≠0 these are genuinely spheroidal (a-dependent
# spheroidicity aω) and are kept SYMBOLIC; substitute their numeric values to evaluate.
_SS0() = Symbolics.variable(:SS0)
_SS1() = Symbolics.variable(:SS1)
_SS2() = Symbolics.variable(:SS2)

# the three raw δ-coefficients {δ, δ', δ''} as Num in (r0sym, OmK[, SS]).  GENERIC (l,m) lookup:
# parse the oracle InputForm string for (l,m) from `_SRC_A0_LM` (a==0) / `_SRC_AKERR_LM` (a≠0).
# s=0 (scalar) is a distinct source structure (single δ coeff, no SWSH-deriv folding) and keeps
# its own small closed form. Full s=-2 set: l=2..5, m=1..l. Unsupported (s,l,m) → clear error.
function _source_delta_coeffs(s::Int, l::Int, m::Int, r0sym::Num, a::Real = 0)
    if s == 0
        (l == 2 && m == 2) ||
            throw(ArgumentError("scalar (s=0) source ported only for (l,m)=(2,2); got ($s,$l,$m)"))
        # -(Sqrt[15 Pi/2] Sqrt[(-3+r0) Sqrt[r0]]) / r0^(3/4); only the δ coefficient (a==0).
        iszero(a) || throw(ArgumentError("scalar (s=0) source ported only at a==0; got a=$a"))
        sq = Num(sqrt(big(15)) / sqrt(big(2))) * _sqrtpi()  # Sqrt[15 Pi/2]
        d0 = -(sq * sqrt((-3 + r0sym) * sqrt(r0sym))) / r0sym^(Num(3 // 4))
        return (d0, Num(0), Num(0))
    end
    s == -2 || throw(ArgumentError("mode-PN source supports s ∈ {-2, 0}; got s=$s"))
    table = iszero(a) ? _SRC_A0_LM : _SRC_AKERR_LM
    entry = get(table, (l, m), nothing)
    entry === nothing && throw(ArgumentError(
        "source delta-coeffs ported only for s=-2, l=2..5, m=1..l (+ scalar (0,2,2)); got ($s,$l,$m) a=$a"))
    (_mma_to_num(entry[1], r0sym, a), _mma_to_num(entry[2], r0sym, a), _mma_to_num(entry[3], r0sym, a))
end

const _SQRTPI = Symbolics.variable(:SqrtPi)   # symbol for Sqrt[Pi] (scalar s=0 path; => sqrt(pi))
_sqrtpi() = _SQRTPI

# Parse an MMA InputForm string (alphabet: Sqrt, Pi, I, r0, OmK, SS0/SS1/SS2, rationals,
# +-*/^ ()) into a Num. `r0sym` is the r0 symbol; OmK -> the ΩKerr symbol; Pi -> the Pi symbol;
# I -> the imag-unit symbol; SS0/SS1/SS2 -> their symbols. The spin is already substituted
# numerically in the oracle string (a=0 folded / a=1/10), so `aval` is unused here but kept in
# the signature for caller clarity. Sqrt[x] is rewritten to sqrt(x) (bracket-aware) before Julia
# `Meta.parse`; the resulting Expr tree is walked by _eval_mma_ast (NO `eval`, NO world-age).
function _mma_to_num(str::AbstractString, r0sym::Num, aval::Real)
    jl = _sqrt_brackets_to_parens(String(str))
    ast = Meta.parse(jl)
    env = Dict{Symbol,Num}(:r0 => r0sym, :OmK => _OMK(),
        :Pi => _PISYM, :I => _IU(), :SS0 => _SS0(), :SS1 => _SS1(), :SS2 => _SS2())
    _eval_mma_ast(ast, env)
end

# Rewrite every `Sqrt[ ... ]` (possibly nested) to `sqrt( ... )`. Single left-to-right pass:
# `Sqrt[` -> `sqrt(`, then a `[`/`]` bracket stack turns the matching `]` into `)`; nested
# `Sqrt[` inside the body are detected the same way (the scan never skips ahead). The ONLY
# `[...]` in the source InputForm is `Sqrt[...]`, so a `[` only ever follows `Sqrt`.
function _sqrt_brackets_to_parens(s::String)
    out = IOBuffer()
    chars = collect(s)
    i = 1
    n = length(chars)
    while i <= n
        if i + 4 <= n && chars[i] == 'S' && chars[i+1] == 'q' && chars[i+2] == 'r' &&
           chars[i+3] == 't' && chars[i+4] == '['
            print(out, "sqrt(")
            i += 5
        elseif chars[i] == ']'
            print(out, ')'); i += 1
        else
            print(out, chars[i]); i += 1
        end
    end
    String(take!(out))
end

# Walk a parsed Julia Expr (from the MMA InputForm) into a Num.  Handles +,-,*,/,^,sqrt and
# leaves (numbers, rationals via `a/b`, the bound symbols).  Any other head/symbol is an error
# (so an unexpected source token surfaces loudly rather than silently mis-evaluating).
function _eval_mma_ast(x, env::Dict{Symbol,Num})
    if x isa Number
        return Num(x)
    elseif x isa Symbol
        haskey(env, x) || throw(ArgumentError("_eval_mma_ast: unbound symbol $x"))
        return env[x]
    elseif x isa Expr && x.head === :call
        op = x.args[1]
        as = [_eval_mma_ast(a, env) for a in x.args[2:end]]
        if op === :+ ; return sum(as)
        elseif op === :* ; return prod(as)
        elseif op === :- ; return length(as) == 1 ? -as[1] : as[1] - as[2]
        elseif op === :/ ; return as[1] / as[2]
        elseif op === :^ ; return as[1] ^ as[2]
        elseif op === :sqrt ; return sqrt(as[1])
        else
            throw(ArgumentError("_eval_mma_ast: unsupported call op $op"))
        end
    else
        throw(ArgumentError("_eval_mma_ast: unexpected node $(repr(x))"))
    end
end

# PN-scale a source coefficient (r0->r0 η⁻², ΩKerr->ΩKerr η³) and expand as an η-PNSeries
# (den 2) to O[η]^(nmax/2).  The source carries nested orbital factors `Sqrt[(-3+r0)Sqrt[r0]]`
# and `(-2+r0)^k` in denominators; after PN scaling these become nested-sqrt-of-Laurent in η.
# `Symbolics.taylor`/PowerExpand cannot expand them — Symbolics will not cancel u^a against a
# buried `1/u^b`, so the "shifted" remainder is still singular at u=0 (→ Int(NaN) in taylor).
#
# Instead we substitute η=u² (half-int η -> integer u) and evaluate the coefficient's EXPRESSION
# TREE directly with truncated-Laurent (PNSeries-in-u) arithmetic: every +,*,/,integer-^,sqrt and
# fractional-^ maps to the corresponding PNSeries op, with fractional powers via the proven
# `(b0 u^q)(1+w)^p` binomial-exp/log route (the same `_log1p_series`/`_exp_series` slice-3 uses).
# This never forms a singular intermediate.  Result: u-slot k -> η-slot k, den 2.  R3.
function _source_coeff_series(coeff::Num, nmax::Int, r0sym::Num)
    OmK = _OMK()
    ηv = Symbolics.variable(:η)
    uv = Symbolics.variable(:_u)
    scaled = Symbolics.substitute(coeff, Dict(r0sym => r0sym * ηv^(-2), OmK => OmK * ηv^3))
    eu = Symbolics.substitute(scaled, Dict(ηv => uv^2))    # half-int η -> integer u
    ser = _tree_to_useries(Symbolics.value(eu), uv, nmax)  # den-1 PNSeries in u
    # relabel u-slots as den-2 η-slots; carry the requested O[u]^nmax window across (den 2).
    PNSeries(:η, ser.x0, ser.coeffs, ser.nmin, nmax, 2)
end

# zero/const/monomial den-1 u-series helpers (window nmax), reusing the slice-3 eta helpers.
_u_zero(nmax::Int) = _zero_eta(nmax)
_u_const(c, nmax::Int) = _const_eta(c, nmax)
_u_mono(c, p::Int, nmax::Int) =
    p >= 0 ? _mono_eta(c, p, nmax) : PNSeries(:η, Num[Num(c)], p, nmax, 1)   # allow Laurent p<0

# Fractional power s^p of a u-Laurent series (p a Rational/Float): factor s = b0 u^q (1+w),
# then s^p = b0^p u^(q p) (1+w)^p with (1+w)^p = exp(p log(1+w)).  Requires q*p ∈ ℤ (true for the
# source's half-integer structure under η=u²).  b0^p kept symbolic (b0 a Num in r0/ΩKerr/SqrtPi).
function _useries_fracpow(s::PNSeries, p, nmax::Int)
    li = findfirst(c -> !iszero(c), s.coeffs)
    li === nothing && return _u_zero(nmax)                  # 0^p = 0 (p>0)
    q = s.nmin + (li - 1)
    b0 = s.coeffs[li]
    qp = q * p
    isinteger(qp) || throw(ArgumentError("_useries_fracpow: q*p=$qp not integer (q=$q, p=$p)"))
    norm = _trunc_eta(s * _u_mono(inv(Num(b0)), -q, nmax), nmax)  # s/(b0 u^q): lead 0, const 1
    w = norm + Num(-1)                                       # w = norm - 1, lead >= 1
    inner = _log1p_series(w, nmax)                           # log(1+w)
    eser = _exp_series(inner * Num(p), nmax)                 # (1+w)^p
    res = _scale_series(eser, Num(b0)^Num(p))
    _trunc_eta(res * _u_mono(Num(1), Int(qp), nmax), nmax)
end

# Evaluate the coefficient expression tree (η already replaced by uv²) into a den-1 PNSeries
# in u, truncated to O[u]^nmax.  Leaf uv -> u; any other leaf (r0/ΩKerr/SqrtPi/imag-unit/number)
# -> a constant series.  +,*,/ ,integer-^ ,fractional-^ ,sqrt map to the PNSeries ops above.
function _tree_to_useries(t, uv::Num, nmax::Int)
    uvv = Symbolics.value(uv)
    if !Symbolics.iscall(t)
        return isequal(t, uvv) ? _u_mono(Num(1), 1, nmax) : _u_const(Num(t), nmax)
    end
    op = Symbolics.operation(t)
    args = Symbolics.arguments(t)
    if op === (+)
        acc = _u_zero(nmax)
        for a in args
            acc = acc + _tree_to_useries(Symbolics.value(a), uv, nmax)
        end
        return acc
    elseif op === (*)
        acc = _u_const(Num(1), nmax)
        for a in args
            acc = _trunc_eta(acc * _tree_to_useries(Symbolics.value(a), uv, nmax), nmax)
        end
        return acc
    elseif op === (/)
        num = _tree_to_useries(Symbolics.value(args[1]), uv, nmax)
        den = _tree_to_useries(Symbolics.value(args[2]), uv, nmax)
        return _trunc_eta(num * inv(den), nmax)
    elseif op === (^)
        base = _tree_to_useries(Symbolics.value(args[1]), uv, nmax)
        p = args[2]
        if p isa Integer
            return _trunc_eta(base^Int(p), nmax)
        else
            # `args[2]` is a raw BasicSymbolic even for a numeric literal; `value` unwraps a constant
            # exponent (e.g. 3//2) to the concrete Julia Rational/Int (Symbolics 7 no longer returns
            # the bare number from the `isa Num` guard).
            pv = Symbolics.value(p)
            pv isa Integer && return _trunc_eta(base^Int(pv), nmax)
            return _useries_fracpow(base, pv, nmax)
        end
    elseif op === sqrt
        return _useries_fracpow(_tree_to_useries(Symbolics.value(args[1]), uv, nmax), 1 // 2, nmax)
    else
        throw(ArgumentError("_tree_to_useries: unsupported operation $op in source coefficient"))
    end
end
# The RadialSourcedAssociation["CO"] assembly (PN.wl 3068-3113) + the public
# TeukolskyPointParticleModePN + the PN energy flux. a==0 circular-equatorial. R3.


# Build ONLY the In radial PNSeries (slice 3), renaming :ω, without the slower Up build.
function _radial_In_only(s::Int, l::Int, m::Int, order::Int, a::Real = 0)
    Rin = _radial_solution(s, l, m, order, :In; a = a)
    Rin  # already in (:η, r, :ω)
end

# Evaluate a slice-3 radial PNSeries (coeffs in r, ω) at r->r0, optionally after p
# r-derivatives. Returns a PNSeries in η whose coeffs are Num in (r0, ω). ω is the slice-3
# omega symbol :ω; we keep it and substitute ω = m ΩKerr at the end.
function _radial_at_r0(R::PNSeries, r0sym::Num, nderiv::Int)
    rsym = Symbolics.variable(:r)
    D = Differential(rsym)
    newcoeffs = Vector{Num}(undef, length(R.coeffs))
    for (i, c) in enumerate(R.coeffs)
        cc = c
        for _ in 1:nderiv
            cc = Symbolics.expand_derivatives(D(cc))
        end
        newcoeffs[i] = Symbolics.substitute(cc, Dict(rsym => r0sym))
    end
    PNSeries(R.var, R.x0, newcoeffs, R.nmin, R.nmax, R.den)
end

# Substitute ω (slice-3 :ω) -> m * ΩKerr in every coeff of an η-PNSeries.
function _omega_to_mOmK(s::PNSeries, m::Int)
    ωs = Symbolics.variable(:ω); OmK = _OMK()
    PNSeries(s.var, s.x0, [Symbolics.substitute(c, Dict(ωs => Num(m) * OmK)) for c in s.coeffs],
        s.nmin, s.nmax, s.den)
end

# Finish an ω-free amplitude η-series: reattach ω=ωnum by grade (slot-g coeff ×ωnum^(g/3))
# and substitute the Log[ω] symbol -> Log[ωnum]. Result: a PNSeries in η with coeffs in ΩKerr.
function _amp_finish(x::PNSeries, ωnum::Num)
    y = _reattach_omega_amp(x, ωnum)
    Lw = _logw()
    PNSeries(y.var, y.x0, [Symbolics.substitute(c, Dict(Lw => Num(log(ωnum)))) for c in y.coeffs],
        y.nmin, y.nmax, y.den)
end

"""
    _radial_sourced_CO(s, l, m, order) -> Dict

The internal RadialSourcedAssociation["CO"] (a==0). Returns
`Dict("I"=>Z^inf::PNSeries, "H"=>Z^H::PNSeries, "W"=>..., "cIn"=>..., "cUp"=>...,
      "Btrans"=>..., "Ctrans"=>..., "Binc"=>..., "srcD"=>(d0,d1,d2))`,
each a PNSeries in :η with Num coeffs in (r0, ΩKerr) (and the imag-unit/transcendental
symbols). Z^inf, Z^H are SeriesTake'd to `order` terms.
"""
function _radial_sourced_CO(s::Int, l::Int, m::Int, order::Int; compute_H::Bool = true,
        a::Real = 0)
    s in (-2, 0) || throw(ArgumentError("mode-PN port supports s in {-2,0}; got s=$s"))
    m != 0 || throw(ArgumentError("mode-PN port supports m != 0 (ω = m Ωφ ≠ 0); got m=0"))
    r0sym = Symbolics.variable(:r0)
    ωsym = Symbolics.variable(:ω)
    OmK = _OMK()

    # --- radial In/Up (slice 3), at r0 + r-derivs; ω -> m ΩKerr ---
    # Z^inf (ℐ) + the energy flux need only R["In"] (via cUp); R["Up"] enters ONLY Z^H (ℋ,
    # via cIn). `compute_H=false` skips the (much slower) Up build for flux-only callers.
    Rin = _radial_In_only(s, l, m, order, a)
    Rup = compute_H ? TeukolskyRadialPN(s, l, m, a, :ω, (:η, order))["Up"] : Rin
    # the η-cutoff to which we must carry the amplitudes & source. The Z leading η-order is
    # (radial-Up-lead) + (source/Wronskian grade). We carry the amplitude/source build to a
    # generous η-window and SeriesTake the final Z to `order`.
    # Up lead η^(-s-l-1); the source δ'' carries r0-derivs (η powers). We use a work window.
    radIn = map(x -> _omega_to_mOmK(x, m),
        (_radial_at_r0(Rin, r0sym, 0), _radial_at_r0(Rin, r0sym, 1), _radial_at_r0(Rin, r0sym, 2)))
    radUp = compute_H ? map(x -> _omega_to_mOmK(x, m),
        (_radial_at_r0(Rup, r0sym, 0), _radial_at_r0(Rup, r0sym, 1), _radial_at_r0(Rup, r0sym, 2))) : radIn

    # working η-cutoff (den-1) for the amplitudes/source/Wronskian. The final Z^inf leads at
    # η^(2(l-s)) (real); keeping `order` terms reaches η^(2(l-s)+order-1). C_trans leads at η^(l-s+1)
    # and the convolution divides by W, so carrying every factor to η^(2(l-s)+order) gives enough
    # headroom for the Cauchy products. Bounded so the slice-2 MST ε-order = ceil(nwork/3)+1 stays
    # ≤ 7 (its scaling cliff) for order ≤ 4.
    nwork = 2 * (l - s) + order

    # --- amplitudes (functions of ω only; built ω-FREE, then ω=m ΩKerr reattached by grade
    #     and the Log[ω] symbol -> Log[m ΩKerr]). Spin shifts κ,τ,εp thread from _amp_inputs;
    #     at a==0 they are (1, ε, ε) and the amplitudes match Schwarzschild byte-for-byte. ---
    nuser, eps, aMSTeta, kap, tauser, epspser = _amp_inputs(s, l, m, a, nwork)
    ωnum = Num(m) * OmK
    finish_amp(x) = _amp_finish(x, ωnum)
    Btrans = finish_amp(_B_trans(s, l, nuser, eps, aMSTeta, nwork, kap, tauser, epspser))
    Ctrans = finish_amp(_C_trans(s, l, nuser, eps, aMSTeta, nwork, kap))
    Binc   = finish_amp(_B_inc(s, l, nuser, eps, aMSTeta, nwork, kap, tauser, epspser))

    # --- Wronskian W = (2 i ω γ) B_inc C_trans, ω = m ΩKerr, γ = η^3 ---
    # γ is the freq-rep expansion variable; InvariantWronskian rescales γ -> η^3 (PN.wl 2315,
    # ChangeSeriesParameter[#, η^3]) after forming (2 i ω γ) B C in the freq rep (PN.wl 2303).
    # B_inc/C_trans here are already the η-graded forms, so only the explicit γ factor is η^3.
    iu = _IU()
    twoiωγ = _mono_eta(Num(2) * iu * Num(m) * OmK, 3, max(Binc.nmax, Ctrans.nmax))   # (2 i ω) η^3
    W = _trunc_eta(_trunc_eta(twoiωγ * Binc, nwork) * Ctrans, nwork)

    # --- source δ-coefficients, PN-scaled + η-expanded (a≠0: SWSH kept symbolic) ---
    d0, d1, d2 = _source_delta_coeffs(s, l, m, r0sym, a)
    src_nmax = 2 * nwork                                  # den-2 η-window
    sD0 = _source_coeff_series(d0, src_nmax, r0sym)
    sD1 = iszero(d1) ? PNSeries(:η, Num[], src_nmax, src_nmax, 2) : _source_coeff_series(d1, src_nmax, r0sym)
    sD2 = iszero(d2) ? PNSeries(:η, Num[], src_nmax, src_nmax, 2) : _source_coeff_series(d2, src_nmax, r0sym)

    # --- convolution: cUp = (1/W) Σ srcCoeff·{Rin, -η² Rin', η⁴ Rin''} ---
    η2 = _mono_eta(Num(1), 2, nwork); η4 = _mono_eta(Num(1), 4, nwork)
    function _conv(rad)
        t0 = _trunc_eta_d2(sD0 * rad[1])
        t1 = _trunc_eta_d2(sD1 * (_neg(η2) * rad[2]))
        t2 = _trunc_eta_d2(sD2 * (η4 * rad[3]))
        t0 + t1 + t2
    end
    sumIn = _conv(radIn)        # for cUp (Z^inf)
    cUp = _series_take_from(sumIn * inv(W), order)     # Z^inf uses cUp (built from Rin)
    Zinf = _series_take_from(Ctrans * cUp, order)
    # Z^H = B_trans cIn,  cIn built from Rup (skipped when compute_H=false)
    if compute_H
        sumUp = _conv(radUp)
        cIn = _series_take_from(sumUp * inv(W), order)
        ZH = _series_take_from(Btrans * cIn, order)
    else
        cIn = _zero_eta(order); ZH = _zero_eta(order)
    end

    Dict{String,Any}("I" => Zinf, "H" => ZH, "W" => W, "cIn" => cIn, "cUp" => cUp,
        "Btrans" => Btrans, "Ctrans" => Ctrans, "Binc" => Binc, "srcD" => (sD0, sD1, sD2))
end

_neg(s::PNSeries) = PNSeries(s.var, s.x0, [-c for c in s.coeffs], s.nmin, s.nmax, s.den)
# truncate a (possibly den-2) product to keep it bounded: keep the whole thing (no cut).
_trunc_eta_d2(s::PNSeries) = s

# SeriesTake `order` terms from the true leading order (real-order span = order/den-step).
# MMA SeriesTake[s,order]: O[] set to nmin + order*den. Here we mirror series_take.
_series_take_from(s::PNSeries, order::Int) = series_take(s, order)

# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

"""
    TeukolskyPointParticleModePN(s, l, m, a, r0, (η, order)) -> Dict

PN-expanded circular-equatorial point-particle mode (Teukolsky`PN`
TeukolskyPointParticleModePN, PN.wl 3168). Returns a `Dict` with:
  * `"Amplitudes"` => `Dict("I"=>Z^inf::PNSeries, "H"=>Z^H::PNSeries)` — the asymptotic
    amplitudes as η-series with `Num` coeffs in `r0`, `ΩKerr` (=Ω_φ), the imag-unit symbol
    `imagunit_sym()`, `SqrtPi`, EulerGamma, Pi, ...;
  * `"EnergyFlux"` => `Dict("I"=>FluxInf::PNSeries)` — the energy flux to infinity
    `FluxInf = |Z^inf|² ω^(2(1-|s|))/(4π)` (s=-2/0 grav/scalar; matches the numerical
    Teukolsky `energy_flux`). ω = m ΩKerr.
  * `"s","l","m","a","r0","order"` metadata.

SCOPE: circular-equatorial (e=0, x=1), Default normalization, order < the In second-term gap.
Spin `a == 0` (Schwarzschild) for `s ∈ {-2,0}`, `(s,l,m) ∈ {(-2,2,2),(-2,3,2),(0,2,2)}`; spin
`a ≠ 0` (Kerr, numeric a e.g. 1//10) for the dominant `(s,l,m)=(-2,2,2)`. ω = m Ωφ with
Ωφ = 1/(r0^{3/2}+a) (= r0^{-3/2} at a=0) kept as the `ΩKerr` symbol. At a=0 the SWSH fold to
spherical values (no S-symbols remain); at a≠0 the SWSH S, S', S'' stay SYMBOLIC as `SS0/SS1/SS2`
(substitute their numeric spheroidal values at the evaluation a·ω to evaluate). To evaluate:
substitute `imagunit_sym()=>im`, `SqrtPi=>sqrt(pi)`, `Pi`, EulerGamma, `Logω=>log(ω)`, Zeta, and
(a≠0) `SS0/SS1/SS2`, `ΩKerr=>1/(r0^{3/2}+a)`.
"""
function TeukolskyPointParticleModePN(s::Integer, l::Integer, m::Integer, a::Real,
        r0::Real, porder::Tuple{Symbol,<:Integer}; compute_H::Bool = true)
    pvar, order = porder
    iszero(r0) || throw(ArgumentError("r0 must be the radius SYMBOL marker (pass r0=0 unused); use the η-series in r0"))
    order >= 1 || throw(ArgumentError("order must be >= 1; got $order"))
    si, li, mi, oi = Int(s), Int(l), Int(m), Int(order)
    co = _radial_sourced_CO(si, li, mi, oi; compute_H = compute_H, a = a)
    Zinf = co["I"]; ZH = co["H"]
    flux = _flux_inf(si, mi, Zinf, oi)
    amps = Dict{String,PNSeries}("I" => _rename(Zinf, pvar), "H" => _rename(ZH, pvar))
    Dict{String,Any}("Amplitudes" => amps,
        "EnergyFlux" => Dict{String,PNSeries}("I" => _rename(flux, pvar)),
        "s" => si, "l" => li, "m" => mi, "a" => a, "r0" => :r0, "order" => oi)
end

# Alternate signature accepting an r0 SYMBOL directly (the natural one): r0 stays symbolic.
TeukolskyPointParticleModePN(s::Integer, l::Integer, m::Integer, a::Real,
    r0sym::Symbol, porder::Tuple{Symbol,<:Integer}; compute_H::Bool = true) =
    (r0sym === :r0 ? TeukolskyPointParticleModePN(s, l, m, a, 0, porder; compute_H = compute_H) :
     throw(ArgumentError("r0 symbol must be :r0; got :$r0sym")))

# (_rename is shared with slice 2: rename a PNSeries' expansion variable.)

# FluxInf = |Z^inf|² ω^(2(1-|s|))/(4π), ω = m ΩKerr.  |Z|² = Z·conj(Z); conj flips the
# imag-unit symbol 𝕚 -> -𝕚 (and Pi/EulerGamma/SqrtPi/ΩKerr/r0 are real). Returns a PNSeries
# in η whose leading coeff is the Newtonian flux. SeriesTake'd to `order` terms.
function _flux_inf(s::Int, m::Int, Zinf::PNSeries, order::Int)
    iu = _IU(); OmK = _OMK()
    Zc = PNSeries(Zinf.var, Zinf.x0, [_conj_num(c) for c in Zinf.coeffs], Zinf.nmin, Zinf.nmax, Zinf.den)
    absZ2 = Zinf * Zc                                   # |Z|² (den preserved)
    # ω^(2(1-|s|)): s=-2 -> ω^-2, s=0 -> ω^2.  ω = m ΩKerr, sits at η^3 each.
    p = 2 * (1 - abs(s))                                # integer (negative for s=-2)
    ωfac = _mono_eta_signed((Num(m) * OmK)^p, 3 * p, max(absZ2.nmax, 2))
    flux = (absZ2 * ωfac) * (Num(1 // 4) / _PISYM)
    series_take(flux, order)
end

# complex-conjugate a Num by flipping the imag-unit symbol 𝕚 -> -𝕚 (all other symbols real).
function _conj_num(c)
    iu = _IU()
    Symbolics.substitute(Num(c), Dict(iu => -iu))
end

end # module SourceMode
